#DOMVirtualGrid .customer-details {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 4px 0;
    width: 100%;
}

#DOMVirtualGrid .customer-avatar {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    font-size: 12px;
    font-weight: 600;
}

#DOMVirtualGrid .customer-info {
    display: flex;
    flex-direction: column;
    min-width: 0;
}

#DOMVirtualGrid .customer-name {
    margin: 0 0 2px;
    font-size: 14px;
    font-weight: 500;
    line-height: 1.2;
    color: #202124;
}

#DOMVirtualGrid .customer-email {
    margin: 0;
    font-size: 13px;
    line-height: 1.2;
